use core::sync::atomic::{AtomicU32 as A,Ordering as O};static COUNT:A=A::new(0);static VALUE:A=A::new(15);fn receiver()->&'static A{COUNT.fetch_add(1,O::Relaxed);&VALUE}fn operand()->u32{COUNT.fetch_add(10,O::Relaxed);3}fn order()->O{COUNT.fetch_add(100,O::Relaxed);O::Relaxed}fn main(){check(receiver().fetch_and(operand(),order())==15);check(receiver().fetch_or(operand(),order())==3);check(receiver().fetch_xor(operand(),order())==3);check(receiver().fetch_nand(operand(),order())==0);check(COUNT.load(O::Relaxed)==444);check(VALUE.load(O::Relaxed)==4294967295);}
